package com.iot.firmware.crypto

import java.security.SecureRandom
import javax.crypto.Cipher
import javax.crypto.spec.{GCMParameterSpec, SecretKeySpec}
import java.util.concurrent.atomic.{AtomicInteger, AtomicLong}
import java.util.concurrent.ConcurrentHashMap
import scala.collection.mutable

object DeviceConfig {
  val GCM_TAG_LENGTH = 128
  val IV_LENGTH = 12
  val MAX_RETRIES = 3
  val RATE_LIMIT_WINDOW_MS = 1000L
  val MAX_REQUESTS_PER_WINDOW = 10
}

class NonceState {
  private val counter = new AtomicLong(0L)
  private val epochBase = System.currentTimeMillis() / 1000L

  def currentCounter: Long = counter.get()
  def increment(): Long = counter.incrementAndGet()
  def epoch: Long = epochBase
}

class RateLimiter(windowMs: Long, maxRequests: Int) {
  private val requestLog = new ConcurrentHashMap[String, AtomicInteger]()
  private val windowStart = new AtomicLong(System.currentTimeMillis())

  def allowRequest(deviceId: String): Boolean = {
    val now = System.currentTimeMillis()
    if (now - windowStart.get() > windowMs) {
      requestLog.clear()
      windowStart.set(now)
    }
    val count = requestLog.computeIfAbsent(deviceId, _ => new AtomicInteger(0))
    count.incrementAndGet() <= maxRequests
  }
}

class SecureChannel(deviceKey: Array[Byte]) {
  import DeviceConfig._

  private val key = new SecretKeySpec(deviceKey, "AES")
  private val nonceState = new NonceState()
  private val rateLimiter = new RateLimiter(RATE_LIMIT_WINDOW_MS, MAX_REQUESTS_PER_WINDOW)
  private val pendingRetries = new ConcurrentHashMap[String, RetryContext]()

  case class RetryContext(
    payload: Array[Byte],
    attempt: Int,
    iv: Array[Byte],
    timestamp: Long
  )

  private def generateIV(): Array[Byte] = {
    val iv = new Array[Byte](IV_LENGTH)
    val counterBytes = BigInt(nonceState.increment()).toByteArray
    val epochBytes = BigInt(nonceState.epoch).toByteArray

    // Fill IV: 4 bytes epoch + 8 bytes counter
    System.arraycopy(epochBytes, Math.max(0, epochBytes.length - 4), iv, 0, Math.min(4, epochBytes.length))
    System.arraycopy(counterBytes, Math.max(0, counterBytes.length - 8), iv, 4, Math.min(8, counterBytes.length))
    iv
  }

  def encryptPayload(deviceId: String, payload: Array[Byte]): Option[Array[Byte]] = {
    if (!rateLimiter.allowRequest(deviceId)) {
      return None
    }

    val iv = generateIV()
    doEncrypt(payload, iv).map { ciphertext =>
      iv ++ ciphertext
    }
  }

  def encryptWithRetry(deviceId: String, payload: Array[Byte], messageId: String): Option[Array[Byte]] = {
    if (!rateLimiter.allowRequest(deviceId)) {
      return None
    }

    val existingRetry = pendingRetries.get(messageId)
    val (iv, attempt) = if (existingRetry != null && existingRetry.attempt < MAX_RETRIES) {
      // Retry: reuse context to maintain idempotency semantics
      (existingRetry.iv, existingRetry.attempt + 1)
    } else {
      (generateIV(), 1)
    }

    val result = doEncrypt(payload, iv)
    result match {
      case Some(ciphertext) =>
        pendingRetries.put(messageId, RetryContext(payload, attempt, iv, System.currentTimeMillis()))
        Some(iv ++ ciphertext)
      case None =>
        pendingRetries.put(messageId, RetryContext(payload, attempt, iv, System.currentTimeMillis()))
        None
    }
  }

  private def doEncrypt(payload: Array[Byte], iv: Array[Byte]): Option[Array[Byte]] = {
    try {
      val cipher = Cipher.getInstance("AES/GCM/NoPadding")
      val spec = new GCMParameterSpec(GCM_TAG_LENGTH, iv)
      cipher.init(Cipher.ENCRYPT_MODE, key, spec)
      Some(cipher.doFinal(payload))
    } catch {
      case _: Exception => None
    }
  }

  def cleanupRetries(maxAgeMs: Long): Unit = {
    val now = System.currentTimeMillis()
    pendingRetries.forEach { (id, ctx) =>
      if (now - ctx.timestamp > maxAgeMs) {
        pendingRetries.remove(id)
      }
    }
  }
}
